    const movement=(code,list,normal='debit')=>list.filter(x=>x.code===code).reduce((s,x)=>s+(normal==='credit'?Number(x.credit||0)-Number(x.debit||0):Number(x.debit||0)-Number(x.credit||0)),0);
    const title=activeView||(kind==='books'?'科目余额表':'资产负债表');let cols=[],rows=[],hint='按已审核凭证及已录入期初余额计算',toolbar='';
